  { k: '5,614 km', n: 'Dingo Fence', d: 'The longest fence in the world, built to keep dingoes away from sheep in the south-east.', t: 'Geography' },
  { k: '146.6 km', n: '90 Mile Straight', d: 'The longest straight stretch of sealed road in the country, on the Eyre Highway.', t: 'Geography', w: 'Eyre Highway' },
  { k: '478 km', n: 'Straight railway', d: 'The longest stretch of dead-straight railway in the world, across the Nullarbor Plain.', t: 'Geography', w: 'Trans-Australian Railway' },
  { k: '2,300 km', n: 'Great Barrier Reef', d: 'The biggest reef system on the planet, visible from space.', t: 'Nature' },
  { k: '1,650 km²', n: 'K’gari (Fraser Island)', d: 'The biggest sand island in the world, with freshwater lakes and rainforest.', t: 'Nature', w: 'K\'gari' },
  { k: '1.7m km²', n: 'Great Artesian Basin', d: 'One of the largest underground water reserves in the world, beneath 22% of the country.', t: 'Nature' },
  { k: '60,000+ years', n: 'Oldest living culture', d: 'Aboriginal and Torres Strait Islander peoples have the oldest continuous culture on Earth.', t: 'Society', w: 'Aboriginal Australians' },
  { k: '6th', n: 'Biggest country', d: '7.69 million km², almost the size of Brazil (8.5 million). And the only country that covers a whole continent.', t: 'Rankings' },
  { k: 'A$26.44/hr', n: 'Minimum wage', d: 'The national minimum wage since July 2026 (A$1,004.90 a week), one of the highest in the world.', t: 'Rankings', w: 'Minimum wage in Australia' },
  { k: '15', n: 'Nobel Prizes', d: 'Eight in Medicine, including Howard Florey (penicillin) and Peter Doherty (the immune system). Patrick White won for Literature in 1973.', t: 'Rankings', w: 'List of Australian Nobel laureates' },
  { k: '~90%', n: 'Voter turnout', d: 'Voting has been compulsory since 1924 and you get fined if you don’t. The result is one of the highest turnouts in the world.', t: 'Society', w: 'Compulsory voting in Australia' },
  { k: '1902', n: 'Women’s vote', d: 'One of the first countries to give women the right to vote and stand in national elections.', t: 'Society', w: 'Women\'s suffrage in Australia' },
  { k: '100,024', n: 'The MCG', d: 'The Melbourne Cricket Ground is the biggest stadium in the southern hemisphere and the biggest cricket ground in the world.', t: 'Society', w: 'Melbourne Cricket Ground' },
  { k: '1st', n: 'Gambling losses', d: 'Australians lose more money gambling per person than anyone in the world, driven by the “pokies”.', t: 'Rankings', w: 'Gambling in Australia' },
  { k: '1st', n: 'Most venomous snake', d: 'The inland taipan has the most potent venom of any land snake. It’s shy and lives far from everything.', t: 'Nature', w: 'Inland taipan' },
  { k: '858 m', n: 'Mount Augustus', d: 'Often called the biggest monolith in the world, twice the size of Uluru.', t: 'Nature' },
  { k: '1861', n: 'The race that stops a nation', d: 'Run since 1861, the Melbourne Cup horse race in November is a public holiday in Melbourne and stops offices right across the country.', t: 'Society' }
