/* ============ HISTORY ============ */
historia: [
  { y: '65,000–50,000 BC', n: 'The First Peoples', d: 'The ancestors of Aboriginal people arrive on the continent. The oldest continuous living culture on Earth begins, with hundreds of nations and languages.', t: 'First Peoples' },
  { y: '1606', n: 'The Dutch', d: 'Willem Janszoon, aboard the Duyfken, is the first recorded European to set foot in Australia, on Cape York.', t: 'Colonisation' },
  { y: '1770', n: 'James Cook', d: 'The British captain charts the east coast, lands at Botany Bay and claims the land for the Crown.', t: 'Colonisation' },
  { y: '26 Jan 1788', n: 'The First Fleet', d: 'Eleven ships carrying about 1,400 people, half of them convicts, found the penal colony at Sydney Cove. The date is Australia Day, which many Indigenous people call Invasion Day.', t: 'Colonisation' },
  { y: '1788–1868', n: 'A convict colony', d: 'Around 162,000 convicts are transported from Britain. The last ship arrives in Western Australia in 1868.', t: 'Colonisation' },
  { y: '1851', n: 'The gold rush', d: 'Gold in NSW and Victoria sends the population soaring and makes Melbourne one of the richest cities in the world.', t: 'Nation' },
  { y: '1854', n: 'Eureka Stockade', d: 'Miners at Ballarat rebel against the colonial government. The uprising is seen as the birthplace of Australian democracy.', t: 'Nation' },
  { y: '1880', n: 'Ned Kelly', d: 'The outlaw in iron armour is hanged in Melbourne and becomes a national legend.', t: 'Nation' },
  { y: '1 Jan 1901', n: 'Federation', d: 'The six colonies unite to form the Commonwealth of Australia. The same year, the White Australia policy begins.', t: 'Nation' },
  { y: '1902', n: 'Votes for women', d: 'Women (but not Indigenous women) win the right to vote and stand in federal elections.', t: 'Nation' },
  { y: '25 Apr 1915', n: 'Gallipoli', d: 'ANZAC troops land in Turkey. The defeat becomes a founding myth; 25 April is Anzac Day.', t: 'War' },
  { y: '1932', n: 'Harbour Bridge', d: 'Sydney’s bridge opens. The same year, the Great Emu War takes place.', t: 'Nation' },
  { y: '1942', n: 'Darwin bombed', d: 'In World War II Japan attacks Darwin, the biggest foreign attack ever on Australian soil.', t: 'War' },
  { y: '1945', n: '“Populate or perish”', d: 'Mass post-war migration begins, with British, Italian, Greek and other European arrivals. More than 7 million people would come in the following decades.', t: 'Society' },
  { y: '1956', n: 'Melbourne Olympics', d: 'The first Games in the southern hemisphere. Television arrives the same year.', t: 'Society' },
  { y: '1966', n: 'The dollar arrives', d: 'Decimal currency replaces the Australian pound.', t: 'Society' },
  { y: '1967', n: 'A historic referendum', d: '90.77% vote for Aboriginal people to be counted in the Census and covered by federal laws.', t: 'First Peoples' },
  { y: '1973', n: 'White Australia ends', d: 'The Whitlam government finally abandons race-based immigration policy. The Opera House opens.', t: 'Society' },
  { y: '1975', n: 'The Dismissal', d: 'The Governor-General sacks Prime Minister Gough Whitlam, the country’s biggest constitutional crisis.', t: 'Nation' },
  { y: '1983', n: 'America’s Cup', d: 'Australia II ends 132 years of American dominance in the race. PM Bob Hawke says any boss who sacks someone for not turning up to work that day “is a bum”.', t: 'Society' },
  { y: '1986', n: 'Australia Act', d: 'The last legal ties with the British Parliament are cut.', t: 'Nation' },
  { y: '1992', n: 'The Mabo decision', d: 'The High Court overturns the idea of “terra nullius” (nobody’s land) and recognises native title.', t: 'First Peoples' },
  { y: '1996', n: 'Port Arthur and guns', d: 'After 35 people are killed in Tasmania, the country passes strict gun laws, with a buyback of 650,000 firearms.', t: 'Society' },
  { y: '1999', n: 'The republic referendum', d: 'Voters reject swapping the monarchy for a republic. The British monarch remains head of state.', t: 'Nation' },
  { y: '2000', n: 'Sydney Olympics', d: 'Aboriginal athlete Cathy Freeman lights the cauldron and wins the 400 m.', t: 'Society' },
  { y: '2008', n: 'The Apology', d: 'PM Kevin Rudd apologises to the Stolen Generations, Indigenous children taken from their families.', t: 'First Peoples' },
  { y: '2017', n: 'Marriage equality', d: 'After a postal survey returns 61.6% “yes”, same-sex marriage becomes law.', t: 'Society' },
  { y: '2019–20', n: 'Black Summer', d: 'Bushfires burn more than 24 million hectares and kill or displace around 3 billion animals.', t: 'Society' },
  { y: '2023', n: 'The Matildas and the Voice', d: 'The women’s team reaches the World Cup semi-final at home and stops the nation. In October, the referendum on an Indigenous Voice to Parliament is defeated.', t: 'First Peoples' },
  { y: '2032', n: 'Olympic Brisbane', d: 'Brisbane will be the third Australian city to host the Olympic Games.', t: 'Society' }
],

